import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  output: "standalone",
  serverExternalPackages: ["xlsx", "mammoth"],
};

export default nextConfig;

const config = {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
};

export default config;

import type { Config } from "tailwindcss";

const config: Config = {
  content: ["./app/**/*.{ts,tsx}", "./components/**/*.{ts,tsx}"],
  theme: {
    extend: {
      colors: {
        ink: {
          DEFAULT: "#1a1a1a",
          soft: "#444",
          faint: "#888",
        },
        accent: {
          DEFAULT: "#ff5a00",
          soft: "#ff7a33",
        },
        panel: "#f7f7f5",
        line: "#e5e3df",
      },
    },
  },
  plugins: [],
};

export default config;

// 统一知识库 schema:整个软件的"大脑"和单一事实源。
// 收敛自两个旧 demo 的散落知识:
//   - 文案副驾: brand-facts(腔调/术语/合规) + style-palette + fewshot
//   - 校对工具: 三方书写标准(术语/格式/语气/法务角色)
// 被三个工具共同消费:文案润色、校对依据、文档填写。

export type StandardRole = "术语" | "格式" | "语气" | "法务";
export const STANDARD_ROLES: StandardRole[] = ["术语", "格式", "语气", "法务"];

// 腔调卡:品牌怎么说话。
export interface ToneCard {
  voice: string;
  do: string[];
  dont: string[];
}

// 合规:广告法违禁词 + 健康宣称边界。
export interface Compliance {
  bannedPhrases: string[];
  healthClaimNote?: string;
}

// 术语条目:跨语言统一表述 + 用法说明。
// 合并旧 BrandTerm(term/preferred/note) 与 UnifiedTerm(category/zh/en/fr)。
export interface Term {
  id: string;
  category?: string;
  zh: string;
  en?: string;
  fr?: string;
  preferred?: string;
  note?: string;
}

// 风格调色板:命名 + 一句话精髓,文案润色时可选注入。
export interface StyleEntry {
  id: string;
  name: string;
  essence: string;
  group: string;
  isDefault?: boolean;
}

// few-shot 范例:只示范风格手法与输出格式,内容与具体任务无关。
export interface FewshotExample {
  id: string;
  input: string;
  output: {
    focus: string;
    text: string;
    intent: string;
    reason: string;
  };
}

// 三方书写标准:某份外部权威标准,在被授权角色内当依据。
export interface WritingStandard {
  id: string;
  name: string;
  text: string;
  note?: string;
  roles: StandardRole[];
}

// 文档模板:供"文档填写"工具使用。body 内用 {{slotKey}} 占位。
export interface TemplateSlot {
  key: string;
  label: string;
  hint?: string;
}

export interface DocumentTemplate {
  id: string;
  name: string;
  description?: string;
  body: string;
  slots: TemplateSlot[];
}

export interface KnowledgeBase {
  meta: {
    brand: string;
    lastReviewed?: string;
    note?: string;
    sources?: string[];
  };
  toneCard: ToneCard;
  terminology: Term[];
  compliance: Compliance;
  stylePalette: StyleEntry[];
  fewshot: FewshotExample[];
  writingStandards: WritingStandard[];
  documentTemplates: DocumentTemplate[];
}

// 每个知识区块的键,供知识库管理 UI 与 @引用统一寻址。
export type KbSection =
  | "toneCard"
  | "terminology"
  | "compliance"
  | "stylePalette"
  | "fewshot"
  | "writingStandards"
  | "documentTemplates";

export const KB_SECTIONS: { key: KbSection; label: string }[] = [
  { key: "toneCard", label: "腔调卡" },
  { key: "terminology", label: "术语库" },
  { key: "compliance", label: "合规" },
  { key: "stylePalette", label: "风格调色板" },
  { key: "fewshot", label: "few-shot 范例" },
  { key: "writingStandards", label: "书写标准" },
  { key: "documentTemplates", label: "文档模板" },
];

// 一次性收敛脚本:把两个旧 demo 里散落的知识抽进统一知识库 data/knowledge-base.json。
// 来源:文案副驾的 brand-facts / style-palette / terminology / fewshot。
// 校对的"三方书写标准"是运行时输入,不预置;只预置一个示例文档模板。
// 用法:node scripts/seed-kb.mjs  (幂等:重跑覆盖 data/knowledge-base.json)

import { promises as fs } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..");
const OLD_DATA = path.resolve(root, "..", "翻译及美化", "copywrite 前端", "data");
const OUT = path.join(root, "data", "knowledge-base.json");

async function readJsonSafe(file, fallback) {
  try {
    return JSON.parse(await fs.readFile(file, "utf-8"));
  } catch {
    console.warn(`[seed] 跳过缺失/无效来源: ${file}`);
    return fallback;
  }
}

function slug(s, i) {
  const base = String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9\u4e00-\u9fa5]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 24);
  return base ? `${base}` : `term-${i}`;
}

async function main() {
  const brand = await readJsonSafe(path.join(OLD_DATA, "brand-facts.json"), {});
  const styles = await readJsonSafe(path.join(OLD_DATA, "style-palette.json"), []);
  const unified = await readJsonSafe(path.join(OLD_DATA, "terminology.json"), []);
  const fewshot = await readJsonSafe(path.join(OLD_DATA, "fewshot.json"), []);

  const terminology = [];
  const seen = new Set();
  // 品牌事实里的术语(带 preferred/note)
  for (const t of brand.terminology || []) {
    const id = slug(t.term || t.preferred, terminology.length);
    const key = id;
    if (seen.has(key)) continue;
    seen.add(key);
    terminology.push({
      id,
      category: t.term && t.preferred ? "品牌核心" : undefined,
      zh: t.preferred && /[\u4e00-\u9fa5]/.test(t.preferred) ? t.preferred : t.term || "",
      preferred: t.preferred,
      note: t.note,
    });
  }
  // 跨语言统一术语
  for (const t of unified) {
    if (!t || !t.zh) continue;
    const id = slug(t.zh, terminology.length);
    let uid = id;
    let n = 2;
    while (seen.has(uid)) uid = `${id}-${n++}`;
    seen.add(uid);
    terminology.push({
      id: uid,
      category: t.category || undefined,
      zh: t.zh,
      en: t.en || undefined,
      fr: t.fr || undefined,
    });
  }

  const kb = {
    meta: {
      brand: brand.brand || "Shokz 韶音",
      lastReviewed: new Date().toISOString().slice(0, 10),
      note: "由 scripts/seed-kb.mjs 从旧 demo 收敛而来,可在知识库管理界面继续编辑。",
      sources: (brand._meta && brand._meta.sources) || [],
    },
    toneCard: {
      voice: (brand.toneCard && brand.toneCard.voice) || "",
      do: (brand.toneCard && brand.toneCard.do) || [],
      dont: (brand.toneCard && brand.toneCard.dont) || [],
    },
    terminology,
    compliance: {
      bannedPhrases: (brand.compliance && brand.compliance.bannedPhrases) || [],
      healthClaimNote: brand.compliance && brand.compliance.healthClaimNote,
    },
    stylePalette: (styles || []).map((s) => ({
      id: s.id,
      name: s.name,
      essence: s.essence,
      group: s.group,
      isDefault: s.isDefault === true,
    })),
    fewshot: (fewshot || []).map((f, i) => ({
      id: `fs-${i + 1}`,
      input: f.input,
      output: f.output,
    })),
    writingStandards: [],
    documentTemplates: [
      {
        id: "tpl-pr",
        name: "新品发布通稿(示例)",
        description: "基于知识库品牌信息自动起草的发布通稿骨架。",
        body: "【{{productName}} 正式发布】\n\n{{brand}} 今日推出 {{productName}}，{{coreClaim}}。\n\n核心卖点:\n{{keyPoints}}\n\n上市信息:{{availability}}",
        slots: [
          { key: "productName", label: "产品名" },
          { key: "brand", label: "品牌名", hint: "默认取知识库 meta.brand" },
          { key: "coreClaim", label: "核心主张" },
          { key: "keyPoints", label: "核心卖点(可多条)" },
          { key: "availability", label: "上市/购买信息" },
        ],
      },
    ],
  };

  await fs.mkdir(path.dirname(OUT), { recursive: true });
  await fs.writeFile(OUT, JSON.stringify(kb, null, 2) + "\n", "utf-8");
  console.log(
    `[seed] 写入 ${OUT}\n  术语 ${terminology.length} 条 · 风格 ${kb.stylePalette.length} 条 · few-shot ${kb.fewshot.length} 条 · 模板 ${kb.documentTemplates.length} 个`
  );
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

import { promises as fs } from "node:fs";
import path from "node:path";
import type {
  KbSection,
  KnowledgeBase,
  Term,
} from "@/lib/kb/types";

// 知识库数据层:统一读写 data/knowledge-base.json(单一事实源)。
// 写入做备份 + 原子写(临时文件 rename),避免写一半损坏。

const DATA_DIR = path.join(process.cwd(), "data");
const KB_PATH = path.join(DATA_DIR, "knowledge-base.json");
const BACKUP_DIR = path.join(DATA_DIR, "backups");

const EMPTY_KB: KnowledgeBase = {
  meta: { brand: "" },
  toneCard: { voice: "", do: [], dont: [] },
  terminology: [],
  compliance: { bannedPhrases: [] },
  stylePalette: [],
  fewshot: [],
  writingStandards: [],
  documentTemplates: [],
};

let cache: { kb: KnowledgeBase; mtimeMs: number } | null = null;

export async function loadKb(): Promise<KnowledgeBase> {
  try {
    const stat = await fs.stat(KB_PATH);
    if (cache && cache.mtimeMs === stat.mtimeMs) return cache.kb;
    const raw = await fs.readFile(KB_PATH, "utf-8");
    const kb = normalize(JSON.parse(raw));
    cache = { kb, mtimeMs: stat.mtimeMs };
    return kb;
  } catch {
    return structuredClone(EMPTY_KB);
  }
}

// 容错归一:旧/缺字段补默认,保证下游字段一定存在。
function normalize(data: unknown): KnowledgeBase {
  const d = (data ?? {}) as Partial<KnowledgeBase>;
  return {
    meta: { brand: "", ...(d.meta ?? {}) },
    toneCard: {
      voice: d.toneCard?.voice ?? "",
      do: d.toneCard?.do ?? [],
      dont: d.toneCard?.dont ?? [],
    },
    terminology: Array.isArray(d.terminology) ? d.terminology : [],
    compliance: {
      bannedPhrases: d.compliance?.bannedPhrases ?? [],
      healthClaimNote: d.compliance?.healthClaimNote,
    },
    stylePalette: Array.isArray(d.stylePalette) ? d.stylePalette : [],
    fewshot: Array.isArray(d.fewshot) ? d.fewshot : [],
    writingStandards: Array.isArray(d.writingStandards) ? d.writingStandards : [],
    documentTemplates: Array.isArray(d.documentTemplates) ? d.documentTemplates : [],
  };
}

async function backupAndWrite(data: KnowledgeBase): Promise<void> {
  try {
    const current = await fs.readFile(KB_PATH, "utf-8");
    await fs.mkdir(BACKUP_DIR, { recursive: true });
    const ts = new Date().toISOString().replace(/[:.]/g, "-");
    await fs.writeFile(
      path.join(BACKUP_DIR, `knowledge-base.${ts}.json`),
      current,
      "utf-8"
    );
  } catch {
    // 首次写入(无旧文件)跳过备份
  }
  await fs.mkdir(DATA_DIR, { recursive: true });
  const tmp = `${KB_PATH}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(data, null, 2) + "\n", "utf-8");
  await fs.rename(tmp, KB_PATH);
  cache = null;
}

export async function saveKb(kb: KnowledgeBase): Promise<void> {
  const stamped: KnowledgeBase = {
    ...kb,
    meta: { ...kb.meta, lastReviewed: new Date().toISOString().slice(0, 10) },
  };
  await backupAndWrite(normalize(stamped));
}

// 单区块更新:管理界面按区块保存,避免整库覆盖竞争。
export async function updateSection(
  section: KbSection,
  value: unknown
): Promise<KnowledgeBase> {
  const kb = await loadKb();
  const next = { ...kb, [section]: value } as KnowledgeBase;
  await saveKb(next);
  return next;
}

// ---- 给工具用的上下文构造 ----

export interface KnowledgeContextOptions {
  styleIds?: string[];
  includeFewshot?: boolean;
  includeTerminology?: boolean;
}

// 把知识库压成一段紧凑文本,作为 LLM 的品牌上下文(防杜撰的硬锚)。
export function buildKnowledgeContext(
  kb: KnowledgeBase,
  opts: KnowledgeContextOptions = {}
): string {
  const lines: string[] = [];
  lines.push(`品牌:${kb.meta.brand || "(未命名)"}`);
  if (kb.toneCard.voice) lines.push(`腔调:${kb.toneCard.voice}`);
  if (kb.toneCard.do.length)
    lines.push(`要这样写:${kb.toneCard.do.join(";")}`);
  if (kb.toneCard.dont.length)
    lines.push(`不要这样写:${kb.toneCard.dont.join(";")}`);
  if (kb.compliance.bannedPhrases.length)
    lines.push(`合规违禁词(禁用):${kb.compliance.bannedPhrases.join("、")}`);
  if (kb.compliance.healthClaimNote)
    lines.push(`健康宣称边界:${kb.compliance.healthClaimNote}`);

  if (opts.includeTerminology !== false && kb.terminology.length) {
    const top = kb.terminology
      .filter((t) => t.zh)
      .slice(0, 60)
      .map((t) => termLine(t))
      .join("\n");
    lines.push(`术语对照(优先表述):\n${top}`);
  }

  if (opts.styleIds && opts.styleIds.length) {
    const picked = kb.stylePalette.filter((s) => opts.styleIds!.includes(s.id));
    if (picked.length)
      lines.push(
        `指定风格:\n${picked.map((s) => `- ${s.name}:${s.essence}`).join("\n")}`
      );
  }

  return lines.join("\n");
}

function termLine(t: Term): string {
  const parts = [t.zh];
  if (t.en) parts.push(t.en);
  if (t.fr) parts.push(t.fr);
  const note = t.preferred && t.preferred !== t.zh ? `(优先:${t.preferred})` : t.note ? `(${t.note})` : "";
  return `- ${parts.join(" / ")}${note}`;
}

export { EMPTY_KB };

import { promises as fs } from "node:fs";
import path from "node:path";

// 模型/密钥配置:本地文件优先,env 兜底。
// API Key 只存本地 config.local.json(已 gitignore),只在服务端读取,绝不进前端 JS。

export interface AppSettings {
  baseUrl: string;
  apiKey: string;
  model: string;
}

const CONFIG_PATH = path.join(process.cwd(), "config.local.json");

const DEFAULTS: AppSettings = {
  baseUrl: "https://api.moonshot.cn/v1",
  apiKey: "",
  model: "kimi-k2.6",
};

export async function getSettings(): Promise<AppSettings> {
  const fromEnv: Partial<AppSettings> = {
    baseUrl: process.env.OPENAI_BASE_URL,
    apiKey: process.env.OPENAI_API_KEY,
    model: process.env.OPENAI_MODEL,
  };
  let fromFile: Partial<AppSettings> = {};
  try {
    fromFile = JSON.parse(await fs.readFile(CONFIG_PATH, "utf-8"));
  } catch {
    // 无本地配置,用 env / 默认
  }
  return {
    baseUrl: fromFile.baseUrl || fromEnv.baseUrl || DEFAULTS.baseUrl,
    apiKey: fromFile.apiKey || fromEnv.apiKey || DEFAULTS.apiKey,
    model: fromFile.model || fromEnv.model || DEFAULTS.model,
  };
}

export async function saveSettings(s: Partial<AppSettings>): Promise<void> {
  const current = await getSettings();
  const next: AppSettings = {
    baseUrl: s.baseUrl ?? current.baseUrl,
    apiKey: s.apiKey ?? current.apiKey,
    model: s.model ?? current.model,
  };
  const tmp = `${CONFIG_PATH}.tmp`;
  await fs.writeFile(tmp, JSON.stringify(next, null, 2) + "\n", "utf-8");
  await fs.rename(tmp, CONFIG_PATH);
}

// 给前端的安全视图:不回传 apiKey 明文,只回传是否已配置。
export async function getSettingsSafe(): Promise<{
  baseUrl: string;
  model: string;
  hasApiKey: boolean;
}> {
  const s = await getSettings();
  return { baseUrl: s.baseUrl, model: s.model, hasApiKey: Boolean(s.apiKey) };
}

import OpenAI from "openai";
import { getSettings } from "@/lib/settings";

// provider 无关的 LLM 客户端:从本地设置(或 env)读取 baseUrl/apiKey/model。
// 改配置即可换模型,不写死任何 provider。

export type Mode = "normal" | "pro";

export const MODES: { id: Mode; label: string; hint: string }[] = [
  { id: "normal", label: "标准", hint: "不开深度思考,出稿快" },
  { id: "pro", label: "专家", hint: "开启深度思考,更慢但质量更高" },
];

export class MissingApiKeyError extends Error {
  constructor() {
    super("尚未配置 API Key,请在右上角「设置」中填写。");
    this.name = "MissingApiKeyError";
  }
}

export async function getClient(): Promise<{ client: OpenAI; model: string }> {
  const s = await getSettings();
  if (!s.apiKey) throw new MissingApiKeyError();
  const client = new OpenAI({
    apiKey: s.apiKey,
    baseURL: s.baseUrl,
    timeout: 240000,
    maxRetries: 2,
  });
  return { client, model: s.model };
}

// 按档位决定思考开关与温度。kimi-k2 用官方 thinking 开关;其它模型只设温度。
export function applyModeParams(
  params: Record<string, unknown>,
  model: string,
  mode?: string
): void {
  const deep = mode === "pro";
  if (model.startsWith("kimi-k2")) {
    params.thinking = { type: deep ? "enabled" : "disabled" };
  }
  params.temperature = deep ? 1 : 0.6;
}

// 一次性 JSON 补全:工具内部用(润色/填写/抽取),非流式,直接解析 JSON。
export async function completeJson<T>(opts: {
  system: string;
  user: string;
  mode?: string;
  maxTokens?: number;
}): Promise<T> {
  const { client, model } = await getClient();
  const params: Record<string, unknown> = {
    model,
    max_tokens: opts.maxTokens ?? 3000,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: opts.system },
      { role: "user", content: opts.user },
    ],
  };
  applyModeParams(params, model, opts.mode);
  const res = await client.chat.completions.create(
    params as unknown as Parameters<typeof client.chat.completions.create>[0]
  );
  const content =
    "choices" in res ? res.choices?.[0]?.message?.content ?? "" : "";
  return JSON.parse(content) as T;
}

// 工具核心的统一返回形态:summary 给 agent 读,canvas 给 UI 富渲染。
// 工具逻辑与界面分离:对话调用和专用界面复用同一套核心。

export type CanvasType = "polish" | "proofread" | "document" | "kb";

export interface ToolResult<T = unknown> {
  ok: boolean;
  summary: string;
  canvas?: { type: CanvasType; data: T };
  error?: string;
}

// ---- 文案润色 ----
export interface PolishVariant {
  focus: string;
  text: string;
  intent: string;
  reason: string;
  charCount?: number;
  complianceHits?: string[];
}

export interface PolishResult {
