// ---- 校对(详见 lib/tools/proofread)----
export interface ProofreadFinding {
  file: string;
  location: string;
  original: string;
  suggestion: string;
  dimension: string;
  subtype: string;
  severity: string;
  confidence: string;
  evidence: string;
}

export interface ProofreadResult {
  findings: ProofreadFinding[];
  noDifference?: boolean;
  notes?: string;
}

// 合规护栏:扫描文本里命中的违禁词(广告法绝对化用语等)。
// 只做提示,不自动改写——最终由人判断。

export function scanBanned(text: string, bannedPhrases: string[]): string[] {
  if (!text) return [];
  const hits: string[] = [];
  for (const phrase of bannedPhrases) {
    if (!phrase) continue;
    if (text.includes(phrase)) hits.push(phrase);
  }
  return Array.from(new Set(hits));
}

import { completeJson } from "@/lib/llm";
import { buildKnowledgeContext, loadKb } from "@/lib/kb/store";
import { scanBanned } from "@/lib/guards";
import type {
  PolishInput,
  PolishResult,
  PolishVariant,
  ToolResult,
} from "@/lib/tools/types";

// 文案润色工具核心:基于统一知识库的品牌上下文,产出多版本润色文案。
// 既被 agent 在对话里调用,也被「文案」专用界面直接调用。

function buildSystem(knowledge: string): string {
  return [
    "你是品牌文案副驾,服务于一个营销团队。基于下面的品牌知识库做文案润色与跨语言美化。",
    "硬纪律:",
    "1. 严格遵守品牌腔调与合规边界;违禁词一律不用。",
    "2. 不杜撰产品事实、规格、数据;术语按知识库的优先表述。",
    "3. 每个版本走一个清晰的写作方向,不要互相雷同。",
    "",
    "【品牌知识库】",
    knowledge,
    "",
    '只输出 JSON,结构:{"variants":[{"focus":"方向名","text":"润色后文案","intent":"表达意向","reason":"为什么这样改"}],"detectedSourceLang":"zh|en|...","notes":"可选说明"}',
  ].join("\n");
}

function buildUser(input: PolishInput): string {
  const lines: string[] = [];
  lines.push(`原文:\n${input.input}`);
  if (input.sourceLang) lines.push(`源语言:${input.sourceLang}`);
  lines.push(`目标语言:${input.targetLang || "保持原语言"}`);
  if (input.channel) lines.push(`投放渠道/场景:${input.channel}`);
  if (input.background) lines.push(`补充背景:${input.background}`);
  lines.push(`请给出 ${input.variantCount ?? 3} 个不同方向的版本。`);
  return lines.join("\n");
}

export async function runPolish(
  input: PolishInput
): Promise<ToolResult<PolishResult>> {
  if (!input.input || !input.input.trim()) {
    return { ok: false, summary: "未提供原文", error: "input 不能为空" };
  }
  const kb = await loadKb();
  const knowledge = buildKnowledgeContext(kb, { styleIds: input.styleIds });

  let raw: PolishResult;
  try {
    raw = await completeJson<PolishResult>({
      system: buildSystem(knowledge),
      user: buildUser(input),
      mode: input.mode,
      maxTokens: 3500,
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, summary: `润色失败:${msg}`, error: msg };
  }

  const banned = kb.compliance.bannedPhrases;
  const variants: PolishVariant[] = (raw.variants || []).map((v) => ({
    focus: v.focus || "",
    text: v.text || "",
    intent: v.intent || "",
    reason: v.reason || "",
    charCount: (v.text || "").length,
    complianceHits: scanBanned(v.text || "", banned),
  }));

  const result: PolishResult = {
    variants,
    detectedSourceLang: raw.detectedSourceLang,
    notes: raw.notes,
  };

  const flagged = variants.filter((v) => (v.complianceHits?.length ?? 0) > 0).length;
  const summary =
    `生成 ${variants.length} 个文案版本` +
    (flagged ? `,其中 ${flagged} 个命中违禁词需人工确认` : "");

  return { ok: true, summary, canvas: { type: "polish", data: result } };
}

import { loadKb } from "@/lib/kb/store";
import { scanBanned } from "@/lib/guards";
import { runPolish } from "@/lib/tools/polish";
import { runFill } from "@/lib/tools/fill";
import type { ToolResult } from "@/lib/tools/types";

// agent 可调用的工具注册表。每个工具:JSON schema 描述 + execute。
// 工具核心是纯逻辑(lib/tools/*),这里只做 agent 入口包装。

export interface ToolDef {
  name: string;
  description: string;
  parameters: Record<string, unknown>;
  execute: (args: Record<string, unknown>, mode?: string) => Promise<ToolResult>;
}

export const TOOLS: ToolDef[] = [
  {
    name: "polish_copy",
    description:
      "润色/翻译/美化营销文案。基于品牌知识库的腔调、术语、合规给出多个不同方向的版本。当用户想写文案、改文案、翻译文案、要slogan/标题时用。",
    parameters: {
      type: "object",
      properties: {
        input: { type: "string", description: "需要润色的原文" },
        targetLang: {
          type: "string",
          description: "目标语言,如 zh/en;不填则保持原语言",
        },
        styleIds: {
          type: "array",
          items: { type: "string" },
          description: "可选的风格调色板 id 列表",
        },
        channel: { type: "string", description: "投放渠道或场景" },
        variantCount: { type: "number", description: "要几个版本,默认3" },
      },
      required: ["input"],
    },
    execute: (args, mode) =>
      runPolish({
        input: String(args.input ?? ""),
        targetLang: args.targetLang ? String(args.targetLang) : undefined,
        styleIds: Array.isArray(args.styleIds)
          ? (args.styleIds as string[])
          : undefined,
        channel: args.channel ? String(args.channel) : undefined,
        variantCount:
          typeof args.variantCount === "number" ? args.variantCount : undefined,
        mode,
      }),
  },
  {
    name: "fill_document",
    description:
      "基于知识库里的文档模板和用户提供的简要信息,自动填写一份营销文档(如发布通稿)。当用户要起草/填写某类文档时用。",
    parameters: {
      type: "object",
      properties: {
        templateId: { type: "string", description: "文档模板 id" },
        brief: { type: "string", description: "用户提供的关键信息/简报" },
      },
      required: ["templateId", "brief"],
    },
    execute: (args, mode) =>
      runFill({
        templateId: String(args.templateId ?? ""),
        brief: String(args.brief ?? ""),
        mode,
      }),
  },
  {
    name: "query_knowledge",
    description:
      "查询品牌知识库:术语、腔调、合规违禁词、风格、文档模板。当需要确认品牌事实或可用资源时用。",
    parameters: {
      type: "object",
      properties: {
        keyword: { type: "string", description: "可选关键词,模糊匹配术语" },
      },
    },
    execute: async (args) => {
      const kb = await loadKb();
      const keyword = args.keyword ? String(args.keyword).toLowerCase() : "";
      const terms = keyword
        ? kb.terminology.filter(
            (t) =>
              t.zh.toLowerCase().includes(keyword) ||
              (t.en ?? "").toLowerCase().includes(keyword)
          )
        : kb.terminology.slice(0, 20);
      const summary = [
        `品牌:${kb.meta.brand}`,
        `腔调:${kb.toneCard.voice}`,
        `违禁词:${kb.compliance.bannedPhrases.join("、")}`,
        `匹配术语 ${terms.length} 条:` +
          terms.map((t) => `${t.zh}=${t.en ?? t.preferred ?? ""}`).join("; "),
        `可用文档模板:${kb.documentTemplates.map((t) => `${t.name}(${t.id})`).join("、") || "无"}`,
      ].join("\n");
      return { ok: true, summary, canvas: { type: "kb", data: { terms } } };
    },
  },
  {
    name: "check_compliance",
    description: "检查一段文本是否命中品牌合规违禁词(广告法绝对化用语等)。",
    parameters: {
      type: "object",
      properties: { text: { type: "string", description: "待检查文本" } },
      required: ["text"],
    },
    execute: async (args) => {
      const kb = await loadKb();
      const hits = scanBanned(String(args.text ?? ""), kb.compliance.bannedPhrases);
      return {
        ok: true,
        summary: hits.length
          ? `命中违禁词:${hits.join("、")}`
          : "未命中违禁词",
      };
    },
  },
];

export function getTool(name: string): ToolDef | undefined {
  return TOOLS.find((t) => t.name === name);
}

export function toolSchemas() {
  return TOOLS.map((t) => ({
    type: "function" as const,
    function: {
      name: t.name,
      description: t.description,
      parameters: t.parameters,
    },
  }));
}

import { completeJson } from "@/lib/llm";
import { buildKnowledgeContext, loadKb } from "@/lib/kb/store";
import { scanBanned } from "@/lib/guards";
import type { DocumentTemplate } from "@/lib/kb/types";
import type { FillInput, FillResult, ToolResult } from "@/lib/tools/types";

// 文档填写工具核心:取知识库模板 + 用户简报,让模型产出每个占位槽的值,
// 再把值套回模板正文。品牌名等可从知识库 meta 兜底。

function buildSystem(knowledge: string, template: DocumentTemplate): string {
  const slotList = template.slots
    .map((s) => `- ${s.key}(${s.label})${s.hint ? `:${s.hint}` : ""}`)
    .join("\n");
  return [
    "你是营销文档起草助手。根据品牌知识库与用户简报,为指定文档模板填写每个占位槽。",
    "纪律:不杜撰事实/数据/规格;遵守品牌腔调与合规违禁词;信息不足的槽用简报里能支撑的内容,缺失就留合理占位并在 notes 说明。",
    "",
    "【品牌知识库】",
    knowledge,
    "",
    `【模板:${template.name}】需要填写的槽:`,
    slotList,
    "",
    '只输出 JSON:{"slots":{"槽key":"该槽的值"},"notes":"可选说明"}',
  ].join("\n");
}

export async function runFill(input: FillInput): Promise<ToolResult<FillResult>> {
  const kb = await loadKb();
  const template = kb.documentTemplates.find((t) => t.id === input.templateId);
  if (!template) {
    return {
      ok: false,
      summary: `找不到模板 ${input.templateId}`,
      error: `可用模板:${kb.documentTemplates.map((t) => t.id).join(", ") || "无"}`,
    };
  }

  const knowledge = buildKnowledgeContext(kb, { includeTerminology: false });

  let raw: { slots?: Record<string, string>; notes?: string };
  try {
    raw = await completeJson<{ slots?: Record<string, string>; notes?: string }>({
      system: buildSystem(knowledge, template),
      user: `用户简报:\n${input.brief}`,
      mode: input.mode,
      maxTokens: 2500,
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, summary: `填写失败:${msg}`, error: msg };
  }

  const values: Record<string, string> = { ...(raw.slots ?? {}) };
  // 品牌名兜底
  if (template.slots.some((s) => s.key === "brand") && !values.brand) {
    values.brand = kb.meta.brand;
  }

  let filled = template.body;
  for (const slot of template.slots) {
    const v = values[slot.key] ?? "";
    filled = filled.split(`{{${slot.key}}}`).join(v);
  }

  const hits = scanBanned(filled, kb.compliance.bannedPhrases);
  const result: FillResult = {
    templateId: template.id,
    templateName: template.name,
    filled,
    slots: template.slots.map((s) => ({
      key: s.key,
      label: s.label,
      value: values[s.key] ?? "",
    })),
    complianceHits: hits,
  };

  const summary =
    `已按模板「${template.name}」填好文档` +
    (hits.length ? `,命中违禁词 ${hits.join("、")} 需人工确认` : "");
  return { ok: true, summary, canvas: { type: "document", data: result } };
}

import { getClient, applyModeParams } from "@/lib/llm";
import { buildKnowledgeContext, loadKb } from "@/lib/kb/store";
import { getTool, toolSchemas } from "@/lib/tools/registry";
import type { CanvasType } from "@/lib/tools/types";

// Agent 编排:OpenAI 风格 function-calling 循环。
// 把对话历史 + 工具交给模型,模型决定调用哪个工具,执行后回灌结果,直到给出最终回答。
// 以事件流(NDJSON)推给前端:tool_call / tool_result / message / error / done。

export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
}

export type AgentEvent =
  | { type: "tool_call"; name: string; args: Record<string, unknown> }
  | {
      type: "tool_result";
      name: string;
      ok: boolean;
      summary: string;
      canvas?: { type: CanvasType; data: unknown };
    }
  | { type: "message"; content: string }
  | { type: "error"; message: string }
  | { type: "done" };

const MAX_STEPS = 6;

function systemPrompt(knowledge: string): string {
  return [
    "你是营销团队的 Agent 助手。你能调用工具完成文案润色、文档填写、知识库查询、合规检查。",
    "工作方式:理解用户意图 -> 需要时调用工具 -> 用简洁中文向用户解释结果。",
    "可以连续调用多个工具完成一个任务(例如先查知识库再润色)。",
    "不杜撰品牌事实;一切以下面的知识库为准。",
    "",
    "【品牌知识库摘要】",
    knowledge,
  ].join("\n");
}

// 内部用的 OpenAI 消息形状(含 tool 角色),用宽松类型避免与 SDK 版本耦合。
type LlmMessage = Record<string, unknown>;

export async function* runAgent(
  history: ChatMessage[],
  mode?: string
): AsyncGenerator<AgentEvent> {
  let client, model;
  try {
    ({ client, model } = await getClient());
  } catch (e) {
    yield { type: "error", message: e instanceof Error ? e.message : String(e) };
    yield { type: "done" };
    return;
  }

  const kb = await loadKb();
  const knowledge = buildKnowledgeContext(kb, { includeTerminology: false });

  const messages: LlmMessage[] = [
    { role: "system", content: systemPrompt(knowledge) },
    ...history.map((m) => ({ role: m.role, content: m.content })),
  ];

  for (let step = 0; step < MAX_STEPS; step++) {
    const params: Record<string, unknown> = {
      model,
      max_tokens: 2500,
      messages,
      tools: toolSchemas(),
      tool_choice: "auto",
    };
    applyModeParams(params, model, mode);

    let res;
    try {
      res = await client.chat.completions.create(
        params as unknown as Parameters<typeof client.chat.completions.create>[0]
      );
    } catch (e) {
      yield { type: "error", message: e instanceof Error ? e.message : String(e) };
      break;
    }

    const choice = "choices" in res ? res.choices?.[0] : undefined;
    const msg = choice?.message as
      | {
          content?: string | null;
          tool_calls?: {
            id: string;
            function: { name: string; arguments: string };
          }[];
        }
      | undefined;

    const toolCalls = msg?.tool_calls ?? [];

    if (toolCalls.length === 0) {
      const content = msg?.content ?? "";
      if (content) yield { type: "message", content };
      break;
    }

    // 记录 assistant 的 tool_calls 回合
    messages.push({
      role: "assistant",
      content: msg?.content ?? "",
      tool_calls: toolCalls,
    });

    for (const call of toolCalls) {
      let args: Record<string, unknown> = {};
      try {
        args = JSON.parse(call.function.arguments || "{}");
      } catch {
        args = {};
      }
      yield { type: "tool_call", name: call.function.name, args };

      const tool = getTool(call.function.name);
      if (!tool) {
        messages.push({
          role: "tool",
          tool_call_id: call.id,
          content: `未知工具 ${call.function.name}`,
        });
        continue;
      }

      const result = await tool.execute(args, mode);
      yield {
        type: "tool_result",
        name: call.function.name,
        ok: result.ok,
        summary: result.summary,
        canvas: result.canvas,
      };
      messages.push({
        role: "tool",
        tool_call_id: call.id,
        content: result.ok
          ? result.summary
          : `失败:${result.error ?? result.summary}`,
      });
    }
  }

  yield { type: "done" };
}

import { runAgent, type ChatMessage } from "@/lib/agent";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: Request) {
  const body = (await req.json()) as {
    messages?: ChatMessage[];
    mode?: string;
  };
  const messages = Array.isArray(body.messages) ? body.messages : [];

  const encoder = new TextEncoder();
  const stream = new ReadableStream({
    async start(controller) {
      try {
        for await (const event of runAgent(messages, body.mode)) {
          controller.enqueue(encoder.encode(JSON.stringify(event) + "\n"));
        }
      } catch (e) {
        controller.enqueue(
          encoder.encode(
            JSON.stringify({
              type: "error",
              message: e instanceof Error ? e.message : String(e),
            }) + "\n"
          )
        );
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
    },
  });
}

