function SettingsModal({ onClose }: { onClose: () => void }) {
  const [baseUrl, setBaseUrl] = useState("");
  const [model, setModel] = useState("");
  const [apiKey, setApiKey] = useState("");
  const [hasApiKey, setHasApiKey] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    fetch("/api/settings")
      .then((r) => r.json())
      .then((s) => {
        setBaseUrl(s.baseUrl || "");
        setModel(s.model || "");
        setHasApiKey(Boolean(s.hasApiKey));
      })
      .catch(() => {});
  }, []);

  async function save() {
    setSaving(true);
    setMsg("");
    try {
      const r = await fetch("/api/settings", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ baseUrl, model, apiKey }),
      });
      const s = await r.json();
      setHasApiKey(Boolean(s.hasApiKey));
      setApiKey("");
      setMsg("已保存");
    } catch {
      setMsg("保存失败");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/30"
      onClick={onClose}
    >
      <div
        className="w-[460px] rounded-lg bg-white p-5 shadow-xl"
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="mb-1 text-base font-semibold">模型设置</h2>
        <p className="mb-4 text-xs text-ink-faint">
          API Key 只存本地、只在服务端读取,不进前端。改 baseURL 即可换 provider。
        </p>
        <label className="mb-3 block">
          <span className="mb-1 block text-xs text-ink-soft">接口地址 (baseURL)</span>
          <input
            value={baseUrl}
            onChange={(e) => setBaseUrl(e.target.value)}
            className="w-full rounded border border-line px-2 py-1.5 text-sm"
            placeholder="https://api.moonshot.cn/v1"
          />
        </label>
        <label className="mb-3 block">
          <span className="mb-1 block text-xs text-ink-soft">模型名</span>
          <input
            value={model}
            onChange={(e) => setModel(e.target.value)}
            className="w-full rounded border border-line px-2 py-1.5 text-sm"
            placeholder="kimi-k2.6"
          />
        </label>
        <label className="mb-4 block">
          <span className="mb-1 block text-xs text-ink-soft">
            API Key {hasApiKey && <span className="text-green-600">· 已配置</span>}
          </span>
          <input
            type="password"
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            className="w-full rounded border border-line px-2 py-1.5 text-sm"
            placeholder={hasApiKey ? "留空则不修改" : "填入 API Key"}
          />
        </label>
        <div className="flex items-center justify-end gap-2">
          {msg && <span className="mr-auto text-xs text-ink-faint">{msg}</span>}
          <button
            onClick={onClose}
            className="rounded border border-line px-3 py-1.5 text-sm hover:bg-panel"
          >
            关闭
          </button>
          <button
            onClick={save}
            disabled={saving}
            className="rounded bg-accent px-3 py-1.5 text-sm text-white hover:bg-accent-soft disabled:opacity-50"
          >
            {saving ? "保存中…" : "保存"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import type {
  FillResult,
  PolishResult,
  PolishVariant,
  ProofreadResult,
} from "@/lib/tools/types";

// 结果画布:把工具返回的结构化结果富渲染。对话和专用界面共用同一套渲染。

export interface CanvasItem {
  type: "polish" | "document" | "kb" | "proofread";
  data: unknown;
  title?: string;
}

export function Canvas({ item }: { item: CanvasItem | null }) {
  if (!item) {
    return (
      <div className="flex h-full items-center justify-center p-8 text-center text-sm text-ink-faint">
        结果画布:文案版本、填好的文档、校对差异表会显示在这里。
        <br />
        在左侧对话里提出需求,或从左侧导航打开专用界面。
      </div>
    );
  }
  switch (item.type) {
    case "polish":
      return <PolishCanvas data={item.data as PolishResult} />;
    case "document":
      return <DocumentCanvas data={item.data as FillResult} />;
    case "proofread":
      return <ProofreadCanvas data={item.data as ProofreadResult} />;
    case "kb":
      return <KbCanvas data={item.data} />;
    default:
      return null;
  }
}

