"use client";

import { useEffect, useRef, useState } from "react";
import { Canvas, type CanvasItem } from "@/components/Canvas";

// Agent 窗口:对话(左) + 结果画布(中) + 知识库上下文(右)。
// 自然语言驱动,agent 调用工具,工具结果在画布富渲染。

interface ChatMessage {
  role: "user" | "assistant";
  content: string;
}

interface TurnEvent {
  kind: "tool_call" | "tool_result" | "text" | "error";
  text: string;
}

type Mode = "normal" | "pro";

export default function AgentWindowPage() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [turn, setTurn] = useState<TurnEvent[]>([]);
  const [input, setInput] = useState("");
  const [mode, setMode] = useState<Mode>("normal");
  const [busy, setBusy] = useState(false);
  const [canvas, setCanvas] = useState<CanvasItem | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [messages, turn]);

  async function send() {
    const text = input.trim();
    if (!text || busy) return;
    const nextMessages = [...messages, { role: "user" as const, content: text }];
    setMessages(nextMessages);
    setInput("");
    setTurn([]);
    setBusy(true);

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ messages: nextMessages, mode }),
      });
      if (!res.body) throw new Error("无响应流");
      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let finalText = "";

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";
        for (const line of lines) {
          if (!line.trim()) continue;
          const ev = JSON.parse(line);
          if (ev.type === "tool_call") {
            setTurn((t) => [
              ...t,
              { kind: "tool_call", text: `调用工具 ${ev.name}` },
            ]);
          } else if (ev.type === "tool_result") {
            setTurn((t) => [
              ...t,
              {
                kind: "tool_result",
                text: `${ev.ok ? "✓" : "✗"} ${ev.name}:${ev.summary}`,
              },
            ]);
            if (ev.canvas) setCanvas({ type: ev.canvas.type, data: ev.canvas.data });
          } else if (ev.type === "message") {
            finalText = ev.content;
          } else if (ev.type === "error") {
            setTurn((t) => [...t, { kind: "error", text: ev.message }]);
          }
        }
      }

      if (finalText) {
        setMessages((m) => [...m, { role: "assistant", content: finalText }]);
      }
    } catch (e) {
      setTurn((t) => [
        ...t,
        { kind: "error", text: e instanceof Error ? e.message : String(e) },
      ]);
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex h-full">
      {/* 对话侧栏 */}
      <section className="flex w-[400px] shrink-0 flex-col border-r border-line">
        <header className="flex items-center justify-between border-b border-line px-3 py-2">
          <span className="text-sm font-semibold">对话</span>
          <ModeToggle mode={mode} onChange={setMode} />
        </header>
        <div ref={scrollRef} className="flex-1 space-y-3 overflow-auto p-3 scrollbar-thin">
          {messages.length === 0 && turn.length === 0 && (
            <div className="mt-8 text-center text-xs text-ink-faint">
              试着说:&ldquo;帮我把这句产品文案润色成3个版本&rdquo;、
              <br />
              &ldquo;用发布通稿模板起草 OpenRun Pro 2 的稿子&rdquo;
            </div>
          )}
          {messages.map((m, i) => (
            <Bubble key={i} role={m.role} content={m.content} />
          ))}
          {turn.length > 0 && (
            <div className="space-y-1 rounded-lg border border-line bg-panel p-2 text-xs">
              {turn.map((e, i) => (
                <div
                  key={i}
                  className={
                    e.kind === "error"
                      ? "text-red-600"
                      : e.kind === "tool_call"
                        ? "text-accent"
                        : "text-ink-soft"
                  }
                >
                  {e.text}
                </div>
              ))}
            </div>
          )}
          {busy && <div className="text-xs text-ink-faint">思考中…</div>}
        </div>
        <div className="border-t border-line p-2">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) send();
            }}
            placeholder="描述你的营销任务… (Ctrl/Cmd+Enter 发送)"
            rows={3}
            className="w-full resize-none rounded border border-line p-2 text-sm focus:border-accent focus:outline-none"
          />
          <div className="mt-1.5 flex justify-end">
            <button
              onClick={send}
              disabled={busy}
              className="rounded bg-accent px-4 py-1.5 text-sm text-white hover:bg-accent-soft disabled:opacity-50"
            >
              发送
            </button>
          </div>
        </div>
      </section>

      {/* 结果画布 */}
      <section className="min-w-0 flex-1 border-r border-line">
        <Canvas item={canvas} />
      </section>

      {/* 知识库上下文 */}
      <KbContextPanel />
    </div>
  );
}

function Bubble({ role, content }: { role: string; content: string }) {
  const isUser = role === "user";
  return (
    <div className={`flex ${isUser ? "justify-end" : "justify-start"}`}>
      <div
        className={`max-w-[85%] whitespace-pre-wrap rounded-lg px-3 py-2 text-sm ${
          isUser ? "bg-accent text-white" : "bg-panel text-ink"
        }`}
      >
        {content}
      </div>
    </div>
  );
}

function ModeToggle({
  mode,
  onChange,
}: {
  mode: Mode;
  onChange: (m: Mode) => void;
}) {
  return (
    <div className="flex rounded border border-line text-xs">
      {(["normal", "pro"] as Mode[]).map((m) => (
        <button
          key={m}
          onClick={() => onChange(m)}
          className={`px-2 py-1 ${
            mode === m ? "bg-accent text-white" : "text-ink-soft"
          }`}
        >
          {m === "normal" ? "标准" : "专家"}
        </button>
      ))}
    </div>
  );
}

interface KbSummary {
