      <h3 className="mb-2 text-xs font-semibold uppercase text-ink-faint">
        知识库上下文
      </h3>
      {!kb ? (
        <p className="text-xs text-ink-faint">加载中…</p>
      ) : (
        <div className="space-y-3 text-xs">
          <div>
            <div className="text-ink-faint">品牌</div>
            <div className="font-medium">{kb.meta.brand}</div>
          </div>
          <div>
            <div className="text-ink-faint">腔调</div>
            <div className="text-ink-soft">{kb.toneCard.voice}</div>
          </div>
          <div>
            <div className="text-ink-faint">术语库</div>
            <div className="text-ink-soft">{kb.terminology.length} 条</div>
          </div>
          <div>
            <div className="mb-1 text-ink-faint">风格调色板</div>
            <div className="flex flex-wrap gap-1">
              {kb.stylePalette.map((s) => (
                <span
                  key={s.id}
                  title={s.essence}
                  className="rounded bg-panel px-1.5 py-0.5 text-ink-soft"
                >
                  {s.name}
                </span>
              ))}
            </div>
          </div>
          <div>
            <div className="text-ink-faint">合规违禁词</div>
            <div className="text-ink-soft">
              {kb.compliance.bannedPhrases.join("、")}
            </div>
          </div>
          <div>
            <div className="text-ink-faint">文档模板</div>
            <div className="text-ink-soft">
              {kb.documentTemplates.map((t) => t.name).join("、") || "无"}
            </div>
          </div>
        </div>
      )}
    </aside>
  );
}

"use client";

import { useEffect, useState } from "react";
import { PolishCanvas } from "@/components/Canvas";
import type { PolishResult, ToolResult } from "@/lib/tools/types";

// 文案专用界面:左输入右多版本。与对话共用同一套润色工具核心(/api/tools/polish)。

interface Style {
  id: string;
  name: string;
  essence: string;
  group: string;
}

export default function PolishPage() {
  const [input, setInput] = useState("");
  const [targetLang, setTargetLang] = useState("");
  const [channel, setChannel] = useState("");
  const [variantCount, setVariantCount] = useState(3);
  const [mode, setMode] = useState("normal");
  const [styleIds, setStyleIds] = useState<string[]>([]);
  const [styles, setStyles] = useState<Style[]>([]);
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState<PolishResult | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    fetch("/api/kb")
      .then((r) => r.json())
      .then((kb) => setStyles(kb.stylePalette ?? []))
      .catch(() => {});
  }, []);

  function toggleStyle(id: string) {
    setStyleIds((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  }

  async function run() {
    if (!input.trim() || busy) return;
    setBusy(true);
    setError("");
    setResult(null);
    try {
      const r = await fetch("/api/tools/polish", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          input,
          targetLang: targetLang || undefined,
          channel: channel || undefined,
          styleIds,
          variantCount,
          mode,
        }),
      });
      const tr = (await r.json()) as ToolResult<PolishResult>;
      if (tr.ok && tr.canvas) setResult(tr.canvas.data);
      else setError(tr.error || tr.summary);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex h-full">
      <section className="flex w-[420px] shrink-0 flex-col overflow-auto border-r border-line p-4 scrollbar-thin">
        <h2 className="mb-3 text-sm font-semibold">文案润色</h2>
        <textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          rows={6}
          placeholder="粘贴需要润色或翻译的文案…"
          className="mb-3 w-full resize-none rounded border border-line p-2 text-sm focus:border-accent focus:outline-none"
        />
        <div className="mb-3 grid grid-cols-2 gap-2">
          <label className="text-xs text-ink-soft">
            目标语言
            <input
              value={targetLang}
              onChange={(e) => setTargetLang(e.target.value)}
              placeholder="保持原语言"
              className="mt-1 w-full rounded border border-line px-2 py-1 text-sm"
            />
          </label>
          <label className="text-xs text-ink-soft">
            渠道/场景
            <input
              value={channel}
              onChange={(e) => setChannel(e.target.value)}
              className="mt-1 w-full rounded border border-line px-2 py-1 text-sm"
            />
          </label>
          <label className="text-xs text-ink-soft">
            版本数
            <input
              type="number"
              min={1}
              max={6}
              value={variantCount}
              onChange={(e) => setVariantCount(Number(e.target.value))}
              className="mt-1 w-full rounded border border-line px-2 py-1 text-sm"
            />
          </label>
          <label className="text-xs text-ink-soft">
            档位
            <select
              value={mode}
              onChange={(e) => setMode(e.target.value)}
              className="mt-1 w-full rounded border border-line px-2 py-1 text-sm"
            >
              <option value="normal">标准</option>
              <option value="pro">专家</option>
            </select>
          </label>
        </div>
        <div className="mb-3">
          <div className="mb-1 text-xs text-ink-soft">风格(可多选)</div>
          <div className="flex flex-wrap gap-1.5">
            {styles.map((s) => (
              <button
                key={s.id}
                title={s.essence}
                onClick={() => toggleStyle(s.id)}
                className={`rounded border px-2 py-0.5 text-xs ${
                  styleIds.includes(s.id)
                    ? "border-accent bg-accent text-white"
                    : "border-line text-ink-soft hover:bg-panel"
                }`}
              >
                {s.name}
              </button>
            ))}
          </div>
        </div>
        <button
          onClick={run}
          disabled={busy}
          className="rounded bg-accent px-4 py-2 text-sm text-white hover:bg-accent-soft disabled:opacity-50"
        >
          {busy ? "生成中…" : "生成多版本"}
        </button>
        {error && <p className="mt-2 text-xs text-red-600">{error}</p>}
      </section>
      <section className="min-w-0 flex-1">
        {result ? (
          <PolishCanvas data={result} />
        ) : (
          <div className="flex h-full items-center justify-center text-sm text-ink-faint">
            左侧填入文案并生成,结果显示在这里。
          </div>
        )}
      </section>
    </div>
  );
}

// Electron 桌面壳。开发态:加载 next dev 的 http://localhost:3000。
// 生产态:打包时把 .next/standalone 放进资源,这里拉起 standalone server 再加载。
// 模型仍走云端 API(本地 config.local.json),只是软件在本机运行。

const { app, BrowserWindow } = require("electron");
const path = require("node:path");
const { spawn } = require("node:child_process");

const DEV_URL = process.env.PMKT_URL || "http://localhost:3000";
let serverProc = null;

function resolveStandaloneServer() {
  // 打包后 standalone 在 resources/standalone/server.js
  const packed = path.join(process.resourcesPath || "", "standalone", "server.js");
  return packed;
}

async function startStandaloneIfPackaged() {
  if (!app.isPackaged) return DEV_URL;
  const server = resolveStandaloneServer();
  const port = 30321;
  serverProc = spawn(process.execPath, [server], {
    env: { ...process.env, PORT: String(port), HOSTNAME: "127.0.0.1" },
    stdio: "ignore",
  });
  // 简单等待端口起来
  await new Promise((r) => setTimeout(r, 1500));
  return `http://127.0.0.1:${port}`;
}

async function createWindow() {
  const url = await startStandaloneIfPackaged();
  const win = new BrowserWindow({
    width: 1280,
    height: 820,
    title: "营销 Agent · PMKT Copilot",
    webPreferences: { contextIsolation: true },
  });
  win.loadURL(url);
}

app.whenReady().then(createWindow);

app.on("window-all-closed", () => {
  if (serverProc) serverProc.kill();
  if (process.platform !== "darwin") app.quit();
});

app.on("activate", () => {
  if (BrowserWindow.getAllWindows().length === 0) createWindow();
});

