import * as XLSX from "xlsx";

// Excel 读取 + 确定性配对。从 Python 校对工具(excel_reader/pairing)迁移到 TS。
// 只读,绝不写回源文件。用 SheetJS 解析,按 sheet 已用区域取单元格(带坐标)。

export interface Cell {
  row: number; // 1-based
  col: number; // 1-based
  letter: string;
  coord: string;
  value: string;
}

export interface SheetGrid {
  sheet: string;
  headerRow: number;
  cells: Cell[];
  a1: string;
}

export interface SheetInfo {
  name: string;
  columns: { index: number; letter: string; header: string }[];
}

function norm(v: unknown): string {
  if (v === null || v === undefined) return "";
  return String(v).replace(/[\r\n]+/g, " ").trim().replace(/\s+/g, " ");
}

export function readWorkbook(buf: ArrayBuffer | Buffer): XLSX.WorkBook {
  return XLSX.read(buf, { type: "buffer" });
}

// 列出每个 sheet 及其首行表头列(供选择关键列)。
export function listSheets(wb: XLSX.WorkBook): SheetInfo[] {
  return wb.SheetNames.map((name) => {
    const ws = wb.Sheets[name];
    const ref = ws["!ref"];
    const columns: SheetInfo["columns"] = [];
    if (ref) {
      const range = XLSX.utils.decode_range(ref);
      for (let c = range.s.c; c <= range.e.c; c++) {
        const addr = XLSX.utils.encode_cell({ r: range.s.r, c });
        columns.push({
          index: c + 1,
          letter: XLSX.utils.encode_col(c),
          header: norm(ws[addr]?.v),
        });
      }
    }
    return { name, columns };
  });
}

// 取整张已用区域的非空单元格(带绝对坐标)。
export function sheetGrid(wb: XLSX.WorkBook, sheet: string): SheetGrid {
  const ws = wb.Sheets[sheet];
  if (!ws) throw new Error(`找不到 sheet:${sheet}`);
  const ref = ws["!ref"] || "A1";
  const range = XLSX.utils.decode_range(ref);
  const cells: Cell[] = [];
  for (let r = range.s.r; r <= range.e.r; r++) {
    for (let c = range.s.c; c <= range.e.c; c++) {
      const addr = XLSX.utils.encode_cell({ r, c });
      const value = norm(ws[addr]?.v);
      if (!value) continue;
      cells.push({
        row: r + 1,
        col: c + 1,
        letter: XLSX.utils.encode_col(c),
        coord: addr,
        value,
      });
    }
  }
  return { sheet, headerRow: range.s.r + 1, cells, a1: ref };
}

export interface RowRecord {
  row: number;
  key: string;
  cells: { coord: string; letter: string; header: string; value: string }[];
}

// 把单元格整理成数据行记录(跳过表头行)。从 pairing.build_row_records 迁移。
export function buildRowRecords(
  grid: SheetGrid,
  keyColIndex?: number
): RowRecord[] {
  const headerByCol = new Map<number, string>();
  for (const cell of grid.cells) {
    if (cell.row === grid.headerRow) headerByCol.set(cell.col, cell.value);
  }
  const byRow = new Map<number, Cell[]>();
  for (const cell of grid.cells) {
    if (cell.row === grid.headerRow) continue;
    if (!byRow.has(cell.row)) byRow.set(cell.row, []);
    byRow.get(cell.row)!.push(cell);
  }
  const records: RowRecord[] = [];
  for (const [row, cells] of [...byRow.entries()].sort((a, b) => a[0] - b[0])) {
    let key = "";
    const recCells = [];
    for (const cell of cells) {
      if (keyColIndex !== undefined && cell.col === keyColIndex) key = cell.value;
      recCells.push({
        coord: cell.coord,
        letter: cell.letter,
        header: headerByCol.get(cell.col) ?? "",
        value: cell.value,
      });
    }
    if (recCells.length === 0) continue;
    records.push({ row, key: key.trim(), cells: recCells });
  }
  return records;
}

export interface PairingResult {
  mode: "row" | "key";
  pairs: { key: string; baseline: RowRecord; target: RowRecord }[];
  unmatchedBaseline: RowRecord[];
  unmatchedTarget: RowRecord[];
}

// 确定性配对。从 pairing.pair 迁移:按行号相对位置,或按关键列(同 key 合并母本)。
export function pair(
  baseline: RowRecord[],
  target: RowRecord[],
  mode: "row" | "key"
): PairingResult {
  const pairs: PairingResult["pairs"] = [];
  const unmatchedBaseline: RowRecord[] = [];
  const unmatchedTarget: RowRecord[] = [];

  if (mode === "key") {
    const bIndex = new Map<string, RowRecord>();
    for (const rec of baseline) {
      if (!rec.key) continue;
      const existing = bIndex.get(rec.key);
      if (existing) existing.cells.push(...rec.cells);
      else bIndex.set(rec.key, { row: rec.row, key: rec.key, cells: [...rec.cells] });
    }
    const matched = new Set<string>();
    for (const trec of target) {
      const brec = trec.key ? bIndex.get(trec.key) : undefined;
      if (brec) {
        matched.add(trec.key);
        pairs.push({ key: trec.key, baseline: brec, target: trec });
      } else {
        unmatchedTarget.push(trec);
      }
    }
    for (const [key, brec] of bIndex.entries()) {
      if (!matched.has(key)) unmatchedBaseline.push(brec);
    }
  } else {
    const n = Math.min(baseline.length, target.length);
    for (let i = 0; i < n; i++) {
      const brec = baseline[i];
      const trec = target[i];
      pairs.push({
        key: brec.key || trec.key || `行${i + 1}`,
        baseline: brec,
        target: trec,
      });
    }
    unmatchedBaseline.push(...baseline.slice(n));
    unmatchedTarget.push(...target.slice(n));
  }

  return { mode, pairs, unmatchedBaseline, unmatchedTarget };
}

import * as XLSX from "xlsx";
import { completeJson } from "@/lib/llm";
import { loadKb } from "@/lib/kb/store";
import {
  buildRowRecords,
  pair,
  readWorkbook,
  sheetGrid,
  type PairingResult,
  type RowRecord,
  type SheetGrid,
} from "@/lib/tools/excel";
import type {
  ProofreadFinding,
  ProofreadResult,
  ToolResult,
} from "@/lib/tools/types";

// 校对工具核心:从 Python(rules/prompt/report) 迁移。五维度评估 + 确定性配对,
// 输出九列差异表。读统一知识库的术语与书写标准作为判据(共享单一事实源)。

export interface DimensionMeta {
  key: string;
  label: string;
  required: boolean;
  defaultOn: boolean;
  subtypes: string[];
  desc: string;
}

export const DIMENSIONS: DimensionMeta[] = [
  {
    key: "accuracy",
    label: "准确性",
    required: true,
    defaultOn: true,
    subtypes: ["产品事实不一致", "参数不一致"],
    desc: "母本↔目标同一单元对比:功能/名称/SKU/URL/装箱清单等事实,或数值/单位/范围/条件等硬参数是否冲突。",
  },
  {
    key: "sync",
    label: "同步",
    required: false,
    defaultOn: true,
    subtypes: ["源文案未同步", "旧版本残留"],
    desc: "关系为翻译或同语言不同版本时,源已改但目标仍旧。",
  },
  {
    key: "consistency",
    label: "一致性",
    required: false,
    defaultOn: true,
    subtypes: ["术语不统一", "格式不统一"],
    desc: "范围内横向扫描:同一概念多种译法/写法、日期/单位/标点/大小写不统一。",
  },
  {
    key: "scope",
    label: "范围",
    required: true,
    defaultOn: true,
    subtypes: ["不在本轮基准范围", "基准冲突", "基准待确认", "语境差异"],
    desc: "安全网:目标超出母本范围标'不在本轮基准范围';母本是?/TBD/空标'基准待确认';两基准打架标'基准冲突'。",
  },
  {
    key: "tone",
    label: "语气",
    required: false,
    defaultOn: false,
    subtypes: ["风格差异", "表达强度差异", "信息颗粒度差异"],
    desc: "事实一致但表达不同:更营销/更技术、绝对词强化或弱化。默认不判错,提示确认。",
  },
];

const RELATIONSHIP_LABEL: Record<string, string> = {
  translation: "翻译关系(母本中文 → 目标外语,查是否同步/译错)",
  same_lang_version: "同语言不同版本(母本是最新版,目标可能是旧版)",
  template_fill: "模板 vs 填写版(母本是标准文案,目标是实际填入内容)",
};

export interface ProofreadConfig {
  baselineSheet: string;
  targetSheet: string;
  pairingMode: "row" | "key";
  baselineKeyCol?: number;
  targetKeyCol?: number;
  relationship: string;
  dimensions: string[];
  baselineName?: string;
  targetName?: string;
}

export function normalizeEnabled(
  enabled: string[],
  relationship: string
): string[] {
  const chosen = new Set(enabled);
  for (const d of DIMENSIONS) if (d.required) chosen.add(d.key);
  if (relationship === "template_fill") chosen.delete("sync");
  return DIMENSIONS.filter((d) => chosen.has(d.key)).map((d) => d.key);
}

const QUALITY_LAYER = `判断质量层(每条 finding 都必须满足):
1. 聚类:同维度 + 同子类型 + 同根因 = 一条 finding;把受影响坐标都列进"位置"。
2. 证据强制:"依据"必须引用母本(或被授权的书写标准)的确切片段 + 位置。引不出能证明问题的片段就降级为"需确认"、置信度"低"。
3. 严重度(错了后果多大)与置信度(有多确定是错)是两个独立维度,不要都填"中"。
4. 母本完整性预检:先核对母本与目标是否同一产品。不一致先在 notes 标注并降低置信度。
5. 不编造:没有差异就 no_difference=true,不要硬凑。`;

function buildSystem(
  enabled: string[],
  relationship: string,
  kbContext: string
): string {
  const dimLines = DIMENSIONS.map((d) => {
    const on = enabled.includes(d.key);
    const flag = on ? "【启用】" : "【关闭,不要输出该类 finding】";
    return `- ${d.label}(${d.key})${flag}:${d.desc}\n  子类型:${d.subtypes.join(" / ")}`;
  }).join("\n");

  return `你是一名严谨的跨文档校对专家。把"目标 Excel"对照"母本 Excel"做校对,找出差异并分类。

源-目标关系:${RELATIONSHIP_LABEL[relationship] ?? relationship}

只读纪律:你只做判断,绝不建议改写母本;母本是唯一事实依据。

五维度评估模型(仅对"启用"维度输出 finding):
${dimLines}

品牌知识库判据(术语统一与合规以此为准,可在"一致性/合规"类判断中作权威依据):
${kbContext}

${QUALITY_LAYER}

输出:严格输出 JSON,结构见用户消息中的 schema。每条 finding 的位置/依据都要带单元格坐标。`;
}

function renderRecord(rec: RowRecord): string {
  const parts = rec.cells
    .filter((c) => c.value)
    .map((c) => `${c.coord}${c.header ? `(${c.header})` : ""}=${c.value}`);
  return parts.length ? parts.join(" ; ") : "(空)";
}

function renderPairs(pairs: PairingResult["pairs"]): string {
  if (!pairs.length) return "(无配对)";
  return pairs
    .map(
      (p, i) =>
        `配对#${i + 1} key=${JSON.stringify(p.key)}\n  母本: ${renderRecord(
          p.baseline
        )}\n  目标: ${renderRecord(p.target)}`
    )
    .join("\n");
}

const MAX_CONTEXT_CELLS = 600;

function renderScope(grid: SheetGrid, title: string): string {
  const byRow = new Map<number, string[]>();
  for (const c of grid.cells.slice(0, MAX_CONTEXT_CELLS)) {
    if (!byRow.has(c.row)) byRow.set(c.row, []);
    byRow.get(c.row)!.push(`${c.letter}${c.row}=${c.value}`);
  }
  const lines = [`${title}(范围 ${grid.a1},sheet=${grid.sheet}):`];
  for (const [, parts] of [...byRow.entries()].sort((a, b) => a[0] - b[0])) {
    lines.push("  " + parts.join(" ; "));
  }
  if (grid.cells.length > MAX_CONTEXT_CELLS)
    lines.push(`  …(单元格超过 ${MAX_CONTEXT_CELLS},已截断)`);
  return lines.join("\n");
}

const OUTPUT_SCHEMA = `{
  "no_difference": "bool,true 表示启用维度下未发现差异",
  "notes": "string,母本完整性预检结论与总体说明",
  "findings": [{
    "file": "目标文件名/区域",
    "location": "单元格坐标;聚类时多个用 / 分隔",
    "original": "目标原文关键片段",
    "suggestion": "建议/处理",
    "dimension": "准确性|同步|一致性|范围|语气",
    "subtype": "对应维度子类型",
    "severity": "高|中|低|可接受差异",
    "confidence": "高|中|低",
    "evidence": "依据:引母本或标准片段+坐标"
  }]
}`;

function buildUser(
  pairing: PairingResult,
  baselineGrid: SheetGrid,
  targetGrid: SheetGrid,
  baselineName: string,
  targetName: string
): string {
  const renderUnmatched = (records: RowRecord[], side: string) =>
    records.length
      ? records
          .map((r) => `  ${side} 行${r.row} key=${JSON.stringify(r.key)}: ${renderRecord(r)}`)
          .join("\n")
      : `(${side}无未匹配行)`;

  return `请校对目标文件「${targetName}」对照母本(${baselineName})。

== 配对单元(已确定性配对,用于准确性/同步判断)==
配对方式:${pairing.mode}
${renderPairs(pairing.pairs)}

== 未匹配行(多与范围/缺失有关)==
${renderUnmatched(pairing.unmatchedBaseline, "母本")}
${renderUnmatched(pairing.unmatchedTarget, "目标")}

== 母本全范围内容(用于一致性/格式/跨版本横向判断)==
${renderScope(baselineGrid, "母本全范围")}

== 目标全范围内容 ==
${renderScope(targetGrid, "目标全范围")}

== 输出 JSON schema(严格按此结构,只输出 JSON)==
${OUTPUT_SCHEMA}`;
}

// 把知识库压成校对判据:术语统一 + 合规违禁词 + 书写标准。
async function buildKbBasis(): Promise<string> {
  const kb = await loadKb();
  const lines: string[] = [];
  if (kb.terminology.length) {
    const terms = kb.terminology
      .filter((t) => t.zh && (t.en || t.preferred))
      .slice(0, 50)
      .map((t) => `${t.zh} = ${t.en ?? t.preferred}`)
      .join("; ");
    lines.push(`统一术语:${terms}`);
  }
  if (kb.compliance.bannedPhrases.length)
    lines.push(`合规违禁词(出现即提示):${kb.compliance.bannedPhrases.join("、")}`);
  for (const std of kb.writingStandards) {
    lines.push(
      `书写标准「${std.name}」(角色:${std.roles.join("、")}):${std.text.slice(0, 800)}`
    );
  }
  return lines.join("\n") || "(知识库无可用判据)";
}

const DIM_LABEL: Record<string, string> = Object.fromEntries(
  DIMENSIONS.map((d) => [d.key, d.label])
);

function normalizeFinding(f: Record<string, unknown>, targetName: string): ProofreadFinding {
  const s = (x: unknown) => (typeof x === "string" ? x : x == null ? "" : String(x));
  return {
    file: s(f.file) || targetName,
    location: s(f.location),
    original: s(f.original),
    suggestion: s(f.suggestion),
    dimension: s(f.dimension),
    subtype: s(f.subtype),
    severity: s(f.severity),
    confidence: s(f.confidence),
    evidence: s(f.evidence),
  };
}

export async function runProofread(
  baselineBuf: ArrayBuffer | Buffer,
  targetBuf: ArrayBuffer | Buffer,
  config: ProofreadConfig
): Promise<ToolResult<ProofreadResult>> {
  let baselineGrid: SheetGrid;
  let targetGrid: SheetGrid;
  try {
    baselineGrid = sheetGrid(readWorkbook(baselineBuf), config.baselineSheet);
    targetGrid = sheetGrid(readWorkbook(targetBuf), config.targetSheet);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, summary: `读取 Excel 失败:${msg}`, error: msg };
  }

  const baselineRecords = buildRowRecords(baselineGrid, config.baselineKeyCol);
  const targetRecords = buildRowRecords(targetGrid, config.targetKeyCol);
  const pairing = pair(baselineRecords, targetRecords, config.pairingMode);

  const enabled = normalizeEnabled(config.dimensions, config.relationship);
  const kbBasis = await buildKbBasis();
  const baselineName = config.baselineName ?? "母本";
  const targetName = config.targetName ?? "目标";

  let raw: { no_difference?: boolean; notes?: string; findings?: unknown[] };
  try {
    raw = await completeJson({
      system: buildSystem(enabled, config.relationship, kbBasis),
      user: buildUser(pairing, baselineGrid, targetGrid, baselineName, targetName),
      maxTokens: 4000,
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return { ok: false, summary: `校对失败:${msg}`, error: msg };
  }

  const findings = (raw.findings ?? []).map((f) =>
    normalizeFinding(f as Record<string, unknown>, targetName)
  );
  const result: ProofreadResult = {
    findings,
    noDifference: raw.no_difference === true && findings.length === 0,
    notes: raw.notes,
  };

  const summary = result.noDifference
    ? "校对完成:未发现差异"
    : `校对完成:发现 ${findings.length} 条差异`;
  return { ok: true, summary, canvas: { type: "proofread", data: result } };
}

// 导出 markdown(九列表)。
export function findingsToMarkdown(result: ProofreadResult): string {
  if (result.noDifference) return "未发现差异。" + (result.notes ? `\n\n${result.notes}` : "");
  const head =
    "| 文件 | 位置 | 原文 | 建议 | 维度 | 子类型 | 严重度 | 置信度 | 依据 |\n|---|---|---|---|---|---|---|---|---|";
  const rows = result.findings.map(
    (f) =>
      `| ${f.file} | ${f.location} | ${f.original} | ${f.suggestion} | ${f.dimension} | ${f.subtype} | ${f.severity} | ${f.confidence} | ${f.evidence} |`
  );
  return [head, ...rows].join("\n");
}

export { XLSX };

import { listSheets, readWorkbook } from "@/lib/tools/excel";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: Request) {
  const form = await req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) {
    return Response.json({ error: "缺少文件" }, { status: 400 });
  }
  try {
    const buf = Buffer.from(await file.arrayBuffer());
    const sheets = listSheets(readWorkbook(buf));
    return Response.json({ sheets });
  } catch (e) {
    return Response.json(
      { error: e instanceof Error ? e.message : String(e) },
      { status: 500 }
    );
  }
}

import { runProofread, type ProofreadConfig } from "@/lib/tools/proofread";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 300;

export async function POST(req: Request) {
  const form = await req.formData();
  const baseline = form.get("baseline");
  const target = form.get("target");
  const configRaw = form.get("config");

  if (!(baseline instanceof File) || !(target instanceof File)) {
    return Response.json({ error: "缺少母本或目标文件" }, { status: 400 });
  }
  let config: ProofreadConfig;
  try {
    config = JSON.parse(String(configRaw ?? "{}"));
  } catch {
    return Response.json({ error: "配置解析失败" }, { status: 400 });
  }

  const baselineBuf = Buffer.from(await baseline.arrayBuffer());
  const targetBuf = Buffer.from(await target.arrayBuffer());
  config.baselineName ??= baseline.name;
  config.targetName ??= target.name;

  const result = await runProofread(baselineBuf, targetBuf, config);
  return Response.json(result);
}

