"use client";

import { useState } from "react";
import { ProofreadCanvas } from "@/components/Canvas";
import type { ProofreadResult, ToolResult } from "@/lib/tools/types";

// 校对三步向导:1 选文件 → 2 配置(sheet/配对/维度/关系) → 3 结果。
// 与 agent 工具共用同一套校对核心(/api/tools/proofread/run)。

interface SheetInfo {
  name: string;
  columns: { index: number; letter: string; header: string }[];
}

const DIMS = [
  { key: "accuracy", label: "准确性", required: true },
  { key: "scope", label: "范围", required: true },
  { key: "consistency", label: "一致性", required: false },
  { key: "sync", label: "同步", required: false },
  { key: "tone", label: "语气", required: false },
];

const RELATIONSHIPS = [
  { key: "translation", label: "翻译(中→外)" },
  { key: "same_lang_version", label: "同语言不同版本" },
  { key: "template_fill", label: "模板 vs 填写版" },
];

export default function ProofreadPage() {
  const [step, setStep] = useState(1);
  const [baseline, setBaseline] = useState<File | null>(null);
  const [target, setTarget] = useState<File | null>(null);
  const [baselineSheets, setBaselineSheets] = useState<SheetInfo[]>([]);
  const [targetSheets, setTargetSheets] = useState<SheetInfo[]>([]);
  const [baselineSheet, setBaselineSheet] = useState("");
  const [targetSheet, setTargetSheet] = useState("");
  const [pairingMode, setPairingMode] = useState<"row" | "key">("row");
  const [baselineKeyCol, setBaselineKeyCol] = useState<number | undefined>();
  const [targetKeyCol, setTargetKeyCol] = useState<number | undefined>();
  const [relationship, setRelationship] = useState("translation");
  const [dimensions, setDimensions] = useState<string[]>([
    "accuracy",
    "scope",
    "consistency",
    "sync",
  ]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<ProofreadResult | null>(null);

  async function inspect(file: File, which: "baseline" | "target") {
    const fd = new FormData();
    fd.append("file", file);
    const r = await fetch("/api/tools/proofread/inspect", {
      method: "POST",
      body: fd,
    });
    const data = await r.json();
    if (data.error) {
      setError(data.error);
      return;
    }
    const sheets: SheetInfo[] = data.sheets ?? [];
    if (which === "baseline") {
      setBaselineSheets(sheets);
      setBaselineSheet(sheets[0]?.name ?? "");
    } else {
      setTargetSheets(sheets);
      setTargetSheet(sheets[0]?.name ?? "");
    }
  }

  function onPick(which: "baseline" | "target", file: File | null) {
    setError("");
    if (which === "baseline") setBaseline(file);
    else setTarget(file);
    if (file) inspect(file, which);
  }

  function toggleDim(key: string) {
    const d = DIMS.find((x) => x.key === key);
    if (d?.required) return;
    setDimensions((cur) =>
      cur.includes(key) ? cur.filter((x) => x !== key) : [...cur, key]
    );
  }

  async function run() {
    if (!baseline || !target) return;
    setBusy(true);
    setError("");
    setResult(null);
    try {
      const fd = new FormData();
      fd.append("baseline", baseline);
      fd.append("target", target);
      fd.append(
        "config",
        JSON.stringify({
          baselineSheet,
          targetSheet,
          pairingMode,
          baselineKeyCol: pairingMode === "key" ? baselineKeyCol : undefined,
          targetKeyCol: pairingMode === "key" ? targetKeyCol : undefined,
          relationship,
          dimensions,
        })
      );
      const r = await fetch("/api/tools/proofread/run", {
        method: "POST",
        body: fd,
      });
      const tr = (await r.json()) as ToolResult<ProofreadResult>;
      if (tr.ok && tr.canvas) {
        setResult(tr.canvas.data);
        setStep(3);
      } else {
        setError(tr.error || tr.summary);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 border-b border-line px-4 py-2">
        <span className="text-sm font-semibold">Excel 校对</span>
        <Stepper step={step} />
      </header>
      <div className="flex min-h-0 flex-1">
        <section className="w-[440px] shrink-0 overflow-auto border-r border-line p-4 scrollbar-thin">
          {step === 1 && (
            <div className="space-y-4">
              <FilePick
                label="母本(标准/事实依据)"
                file={baseline}
                onPick={(f) => onPick("baseline", f)}
              />
              <FilePick
                label="目标(被校对)"
                file={target}
                onPick={(f) => onPick("target", f)}
              />
              <button
                disabled={!baseline || !target}
                onClick={() => setStep(2)}
                className="rounded bg-accent px-4 py-2 text-sm text-white disabled:opacity-50"
              >
                下一步:配置
              </button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-4 text-sm">
              <SheetSelect
                label="母本 sheet"
                sheets={baselineSheets}
                value={baselineSheet}
                onChange={setBaselineSheet}
              />
              <SheetSelect
                label="目标 sheet"
                sheets={targetSheets}
                value={targetSheet}
                onChange={setTargetSheet}
              />
              <div>
                <div className="mb-1 text-xs text-ink-soft">配对方式</div>
                <div className="flex gap-2">
                  {(["row", "key"] as const).map((m) => (
                    <button
                      key={m}
                      onClick={() => setPairingMode(m)}
                      className={`rounded border px-3 py-1 text-xs ${
                        pairingMode === m
                          ? "border-accent bg-accent text-white"
                          : "border-line"
                      }`}
                    >
                      {m === "row" ? "按行号" : "按关键列"}
                    </button>
                  ))}
                </div>
              </div>
              {pairingMode === "key" && (
                <div className="grid grid-cols-2 gap-2">
                  <KeyColSelect
                    label="母本关键列"
                    sheet={baselineSheets.find((s) => s.name === baselineSheet)}
                    value={baselineKeyCol}
                    onChange={setBaselineKeyCol}
                  />
                  <KeyColSelect
                    label="目标关键列"
                    sheet={targetSheets.find((s) => s.name === targetSheet)}
                    value={targetKeyCol}
                    onChange={setTargetKeyCol}
                  />
                </div>
              )}
              <div>
                <div className="mb-1 text-xs text-ink-soft">源-目标关系</div>
                <select
                  value={relationship}
                  onChange={(e) => setRelationship(e.target.value)}
                  className="w-full rounded border border-line px-2 py-1 text-sm"
                >
                  {RELATIONSHIPS.map((r) => (
                    <option key={r.key} value={r.key}>
                      {r.label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <div className="mb-1 text-xs text-ink-soft">评估维度</div>
                <div className="flex flex-wrap gap-1.5">
                  {DIMS.map((d) => (
                    <button
                      key={d.key}
                      onClick={() => toggleDim(d.key)}
                      className={`rounded border px-2 py-0.5 text-xs ${
                        dimensions.includes(d.key)
                          ? "border-accent bg-accent text-white"
                          : "border-line text-ink-soft"
                      } ${d.required ? "opacity-100" : ""}`}
                      title={d.required ? "必选维度" : ""}
                    >
                      {d.label}
                      {d.required ? " ·必选" : ""}
                    </button>
                  ))}
                </div>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => setStep(1)}
                  className="rounded border border-line px-3 py-2 text-sm"
                >
                  上一步
                </button>
                <button
                  onClick={run}
                  disabled={busy}
                  className="rounded bg-accent px-4 py-2 text-sm text-white disabled:opacity-50"
                >
                  {busy ? "校对中…" : "开始校对"}
                </button>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-3 text-sm">
              <p className="text-ink-soft">校对完成。结果见右侧。</p>
              <button
                onClick={() => setStep(2)}
                className="rounded border border-line px-3 py-2 text-sm"
              >
                调整配置重跑
              </button>
              {result && !result.noDifference && (
                <button
                  onClick={() => exportMarkdown(result)}
                  className="ml-2 rounded border border-line px-3 py-2 text-sm"
                >
                  导出 Markdown
                </button>
              )}
            </div>
          )}

          {error && <p className="mt-3 text-xs text-red-600">{error}</p>}
        </section>

        <section className="min-w-0 flex-1">
          {result ? (
            <ProofreadCanvas data={result} />
          ) : (
            <div className="flex h-full items-center justify-center text-sm text-ink-faint">
              完成配置并校对后,九列差异表显示在这里。
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

function exportMarkdown(result: ProofreadResult) {
  const head =
    "| 文件 | 位置 | 原文 | 建议 | 维度 | 子类型 | 严重度 | 置信度 | 依据 |\n|---|---|---|---|---|---|---|---|---|";
  const rows = result.findings.map(
    (f) =>
      `| ${f.file} | ${f.location} | ${f.original} | ${f.suggestion} | ${f.dimension} | ${f.subtype} | ${f.severity} | ${f.confidence} | ${f.evidence} |`
  );
  const md = [head, ...rows].join("\n");
  const blob = new Blob([md], { type: "text/markdown" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "校对结果.md";
  a.click();
  URL.revokeObjectURL(url);
}

function Stepper({ step }: { step: number }) {
  const labels = ["选文件", "配置", "结果"];
  return (
    <div className="flex items-center gap-1 text-xs">
      {labels.map((l, i) => (
        <span
          key={l}
          className={`rounded px-2 py-0.5 ${
            step === i + 1 ? "bg-accent text-white" : "bg-panel text-ink-faint"
          }`}
        >
          {i + 1}.{l}
        </span>
      ))}
    </div>
  );
}

function FilePick({
  label,
  file,
  onPick,
}: {
  label: string;
  file: File | null;
  onPick: (f: File | null) => void;
}) {
  return (
    <label className="block">
      <span className="mb-1 block text-xs text-ink-soft">{label}</span>
      <input
        type="file"
        accept=".xlsx,.xlsm,.xls"
        onChange={(e) => onPick(e.target.files?.[0] ?? null)}
        className="block w-full text-xs"
      />
      {file && <span className="mt-1 block text-xs text-green-600">{file.name}</span>}
    </label>
  );
}

function SheetSelect({
  label,
  sheets,
  value,
  onChange,
}: {
  label: string;
  sheets: SheetInfo[];
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <label className="block">
      <span className="mb-1 block text-xs text-ink-soft">{label}</span>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full rounded border border-line px-2 py-1 text-sm"
      >
        {sheets.map((s) => (
          <option key={s.name} value={s.name}>
            {s.name}
          </option>
        ))}
      </select>
    </label>
  );
}

function KeyColSelect({
  label,
  sheet,
  value,
  onChange,
}: {
  label: string;
  sheet: SheetInfo | undefined;
  value: number | undefined;
  onChange: (v: number) => void;
}) {
  return (
    <label className="block">
      <span className="mb-1 block text-xs text-ink-soft">{label}</span>
      <select
        value={value ?? ""}
        onChange={(e) => onChange(Number(e.target.value))}
        className="w-full rounded border border-line px-2 py-1 text-sm"
      >
        <option value="">选择列</option>
        {sheet?.columns.map((c) => (
          <option key={c.index} value={c.index}>
            {c.letter} · {c.header || "(空表头)"}
          </option>
        ))}
      </select>
    </label>
  );
}

"use client";

import { useEffect, useState } from "react";

// 知识库可视化管理:按区块增删改查,保存到单一事实源 data/knowledge-base.json。

type Section =
  | "toneCard"
  | "compliance"
  | "terminology"
  | "stylePalette"
  | "fewshot"
  | "writingStandards"
  | "documentTemplates";

const SECTIONS: { key: Section; label: string }[] = [
  { key: "toneCard", label: "腔调卡" },
  { key: "terminology", label: "术语库" },
  { key: "compliance", label: "合规" },
  { key: "stylePalette", label: "风格调色板" },
  { key: "fewshot", label: "few-shot 范例" },
  { key: "writingStandards", label: "书写标准" },
  { key: "documentTemplates", label: "文档模板" },
];

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Kb = any;

export default function KbPage() {
  const [kb, setKb] = useState<Kb | null>(null);
  const [section, setSection] = useState<Section>("toneCard");
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    fetch("/api/kb")
      .then((r) => r.json())
      .then(setKb)
      .catch(() => {});
  }, []);

  async function save(value: unknown) {
    setSaving(true);
    setMsg("");
    try {
      const r = await fetch("/api/kb", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ section, value }),
      });
      const next = await r.json();
      if (next.error) setMsg(next.error);
      else {
        setKb(next);
        setMsg("已保存");
      }
    } catch (e) {
      setMsg(e instanceof Error ? e.message : String(e));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="flex h-full">
      <aside className="w-40 shrink-0 border-r border-line p-2">
        <h2 className="mb-2 px-1 text-xs font-semibold uppercase text-ink-faint">
          知识库
        </h2>
        {SECTIONS.map((s) => (
          <button
            key={s.key}
            onClick={() => {
              setSection(s.key);
              setMsg("");
            }}
            className={`mb-0.5 block w-full rounded px-2 py-1.5 text-left text-sm ${
              section === s.key ? "bg-accent text-white" : "hover:bg-panel"
            }`}
          >
            {s.label}
          </button>
        ))}
      </aside>
      <main className="min-w-0 flex-1 overflow-auto p-5 scrollbar-thin">
        {!kb ? (
          <p className="text-sm text-ink-faint">加载中…</p>
        ) : (
          <SectionEditor
            section={section}
            kb={kb}
            onSave={save}
            saving={saving}
            msg={msg}
          />
        )}
      </main>
    </div>
  );
}

function SectionEditor({
  section,
  kb,
  onSave,
  saving,
  msg,
}: {
  section: Section;
  kb: Kb;
  onSave: (v: unknown) => void;
  saving: boolean;
  msg: string;
}) {
  switch (section) {
    case "toneCard":
      return <ToneEditor value={kb.toneCard} onSave={onSave} saving={saving} msg={msg} />;
    case "compliance":
      return (
        <ComplianceEditor value={kb.compliance} onSave={onSave} saving={saving} msg={msg} />
      );
    case "terminology":
      return (
        <TerminologyEditor
          value={kb.terminology}
          onSave={onSave}
          saving={saving}
          msg={msg}
        />
      );
    case "stylePalette":
      return (
        <StyleEditor value={kb.stylePalette} onSave={onSave} saving={saving} msg={msg} />
      );
    case "fewshot":
      return <JsonEditor label="few-shot 范例" value={kb.fewshot} onSave={onSave} saving={saving} msg={msg} />;
    case "writingStandards":
      return (
        <JsonEditor
          label="书写标准"
          value={kb.writingStandards}
          onSave={onSave}
          saving={saving}
          msg={msg}
        />
      );
    case "documentTemplates":
      return (
        <JsonEditor
          label="文档模板"
          value={kb.documentTemplates}
          onSave={onSave}
          saving={saving}
          msg={msg}
        />
      );
  }
}

function SaveBar({ onSave, saving, msg }: { onSave: () => void; saving: boolean; msg: string }) {
  return (
    <div className="mt-4 flex items-center gap-3">
      <button
        onClick={onSave}
        disabled={saving}
        className="rounded bg-accent px-4 py-2 text-sm text-white disabled:opacity-50"
      >
        {saving ? "保存中…" : "保存"}
      </button>
      {msg && <span className="text-xs text-ink-faint">{msg}</span>}
    </div>
  );
}

function toLines(arr: string[]): string {
  return (arr || []).join("\n");
}
function fromLines(s: string): string[] {
  return s
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);
}

function ToneEditor({
  value,
  onSave,
  saving,
  msg,
}: {
  value: { voice: string; do: string[]; dont: string[] };
  onSave: (v: unknown) => void;
  saving: boolean;
  msg: string;
}) {
  const [voice, setVoice] = useState(value.voice || "");
  const [doList, setDoList] = useState(toLines(value.do));
  const [dontList, setDontList] = useState(toLines(value.dont));
  return (
    <div className="max-w-2xl">
      <h2 className="mb-3 text-base font-semibold">腔调卡</h2>
      <Field label="品牌声音 voice">
        <textarea
          value={voice}
          onChange={(e) => setVoice(e.target.value)}
          rows={2}
          className="w-full rounded border border-line p-2 text-sm"
        />
      </Field>
      <Field label="要这样写 do(每行一条)">
        <textarea
          value={doList}
          onChange={(e) => setDoList(e.target.value)}
          rows={4}
          className="w-full rounded border border-line p-2 text-sm"
        />
      </Field>
      <Field label="不要这样写 dont(每行一条)">
        <textarea
          value={dontList}
          onChange={(e) => setDontList(e.target.value)}
          rows={4}
          className="w-full rounded border border-line p-2 text-sm"
        />
      </Field>
      <SaveBar
        saving={saving}
        msg={msg}
        onSave={() =>
          onSave({ voice, do: fromLines(doList), dont: fromLines(dontList) })
        }
      />
    </div>
  );
}

function ComplianceEditor({
  value,
  onSave,
  saving,
  msg,
}: {
  value: { bannedPhrases: string[]; healthClaimNote?: string };
  onSave: (v: unknown) => void;
  saving: boolean;
  msg: string;
}) {
  const [banned, setBanned] = useState(toLines(value.bannedPhrases));
  const [note, setNote] = useState(value.healthClaimNote || "");
  return (
    <div className="max-w-2xl">
      <h2 className="mb-3 text-base font-semibold">合规</h2>
      <Field label="违禁词(每行一条)">
        <textarea
          value={banned}
          onChange={(e) => setBanned(e.target.value)}
          rows={6}
