        value={text}
        onChange={(e) => setText(e.target.value)}
        rows={20}
        className="w-full rounded border border-line p-2 font-mono text-xs"
      />
      {err && <p className="mt-1 text-xs text-red-600">{err}</p>}
      <SaveBar
        saving={saving}
        msg={msg}
        onSave={() => {
          try {
            const parsed = JSON.parse(text);
            setErr("");
            onSave(parsed);
