"use client";

import { useEffect, useState } from "react";
import { DocumentCanvas } from "@/components/Canvas";
import type { FillResult, ToolResult } from "@/lib/tools/types";

// 文档填写专用界面:选模板 + 填简报 → 基于知识库自动起草。
// 与 agent 工具共用同一套填写核心(/api/tools/fill)。

interface TemplateOpt {
  id: string;
  name: string;
  description?: string;
  slots: { key: string; label: string; hint?: string }[];
}

export default function FillPage() {
  const [templates, setTemplates] = useState<TemplateOpt[]>([]);
  const [templateId, setTemplateId] = useState("");
  const [brief, setBrief] = useState("");
  const [mode, setMode] = useState("normal");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<FillResult | null>(null);

  useEffect(() => {
    fetch("/api/kb")
      .then((r) => r.json())
      .then((kb) => {
        const ts: TemplateOpt[] = kb.documentTemplates ?? [];
        setTemplates(ts);
        if (ts[0]) setTemplateId(ts[0].id);
      })
      .catch(() => {});
  }, []);

  const current = templates.find((t) => t.id === templateId);

  async function run() {
    if (!templateId || !brief.trim() || busy) return;
    setBusy(true);
    setError("");
    setResult(null);
    try {
      const r = await fetch("/api/tools/fill", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ templateId, brief, mode }),
      });
      const tr = (await r.json()) as ToolResult<FillResult>;
      if (tr.ok && tr.canvas) setResult(tr.canvas.data);
      else setError(tr.error || tr.summary);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="flex h-full">
      <section className="flex w-[420px] shrink-0 flex-col overflow-auto border-r border-line p-4 scrollbar-thin">
        <h2 className="mb-3 text-sm font-semibold">文档填写</h2>
        <label className="mb-3 block text-xs text-ink-soft">
          模板
          <select
            value={templateId}
            onChange={(e) => setTemplateId(e.target.value)}
            className="mt-1 w-full rounded border border-line px-2 py-1 text-sm"
          >
            {templates.length === 0 && <option value="">(知识库暂无模板)</option>}
            {templates.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name}
              </option>
            ))}
          </select>
        </label>
        {current?.description && (
          <p className="mb-2 text-xs text-ink-faint">{current.description}</p>
        )}
        {current && (
          <div className="mb-3 rounded border border-line bg-panel p-2 text-xs text-ink-soft">
            需要填写的槽:
            {current.slots.map((s) => (
              <span key={s.key} className="ml-1">
                {s.label}
              </span>
            ))}
          </div>
        )}
        <label className="mb-3 block text-xs text-ink-soft">
          简报(把关键信息告诉我,缺的我按知识库兜底)
          <textarea
            value={brief}
            onChange={(e) => setBrief(e.target.value)}
            rows={8}
            placeholder="例:产品 OpenRun Pro 2,主打骨传导舒适佩戴,9月10日官网与天猫同步开售…"
            className="mt-1 w-full resize-none rounded border border-line p-2 text-sm"
          />
        </label>
        <label className="mb-3 block text-xs text-ink-soft">
          档位
          <select
            value={mode}
            onChange={(e) => setMode(e.target.value)}
            className="mt-1 w-full rounded border border-line px-2 py-1 text-sm"
          >
            <option value="normal">标准</option>
            <option value="pro">专家</option>
          </select>
        </label>
        <button
          onClick={run}
          disabled={busy || !templateId}
          className="rounded bg-accent px-4 py-2 text-sm text-white disabled:opacity-50"
        >
          {busy ? "起草中…" : "自动填写"}
        </button>
        {error && <p className="mt-2 text-xs text-red-600">{error}</p>}
      </section>
      <section className="min-w-0 flex-1">
        {result ? (
          <DocumentCanvas data={result} />
        ) : (
          <div className="flex h-full items-center justify-center text-sm text-ink-faint">
            选模板、填简报后,填好的文档显示在这里。
          </div>
        )}
      </section>
    </div>
  );
}

