// 一键桌面窗口:起 next dev,等端口就绪后自动拉起 Electron 窗口。
// 默认 `npm run dev` 用这个;只想要浏览器调试时用 `npm run dev:web`。

import { spawn } from "node:child_process";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const nextBin = require.resolve("next/dist/bin/next");
const electronPath = require("electron"); // electron 模块从 Node 引入时返回可执行文件路径

let url = null;
let electron = null;
let dying = false;

const next = spawn(process.execPath, [nextBin, "dev"], {
  stdio: ["inherit", "pipe", "pipe"],
});

function onLine(buf, sink) {
  const text = buf.toString();
  sink.write(text);
  const m = text.match(/http:\/\/localhost:(\d+)/);
  if (m) url = `http://localhost:${m[1]}`;
  if (/Ready in/.test(text) && url && !electron) startElectron();
}

next.stdout.on("data", (b) => onLine(b, process.stdout));
next.stderr.on("data", (b) => onLine(b, process.stderr));

function startElectron() {
  console.log(`\n[dev-app] 启动桌面窗口 → ${url}\n`);
  electron = spawn(electronPath, ["."], {
    stdio: "inherit",
    env: { ...process.env, PMKT_URL: url },
  });
  electron.on("exit", () => {
    // 关掉窗口即退出整个开发会话
    shutdown(0);
  });
}

function shutdown(code) {
  if (dying) return;
  dying = true;
  if (electron && !electron.killed) electron.kill();
  if (next && !next.killed) next.kill();
  process.exit(code ?? 0);
}

process.on("SIGINT", () => shutdown(0));
process.on("SIGTERM", () => shutdown(0));
next.on("exit", (code) => shutdown(code ?? 0));
